{
  "critique": [
    {
      "design": "r1A",
      "good": "The compact layout keeps the numeric columns easy to compare and all headers and tracking identifiers intact. SKU and warehouse values wrap at hyphens, giving the rows a consistent two-line rhythm.",
      "problems": "The first view cuts through the tracking identifiers, so readers must scroll to see their ends. The warehouse wraps in every row, making the table taller.",
      "cause": "Tracking needs its full 180px, but the table totals 759px. The 102px warehouse column keeps its header intact but leaves too little text width for the full location codes."
    },
    {
      "design": "r1B",
      "good": "The headers and numeric values remain intact, and the item and fulfillment codes wrap at natural breaks.",
      "problems": "The extra SKU width does not visibly reduce wrapping or row height. It moves more of the tracking column beyond the viewport without a compensating benefit.",
      "cause": "Increasing SKU from 95px to 110px is still insufficient for the full SKU values, while increasing total width to 774px."
    },
    {
      "design": "r1C",
      "good": "Full SKUs are easy to scan and compare, while the numeric columns and headers remain intact.",
      "problems": "The unwrapped SKUs do not shorten the rows because warehouse locations still wrap. Tracking begins close to the viewport edge, leaving most of each identifier to be reached by scrolling.",
      "cause": "The 157px SKU column removes SKU wraps, but the 102px warehouse column still forces two-line rows. Together with the 180px tracking column, the table reaches 821px."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "compact-warehouse",
      "widths": [38, 95, 61, 52, 47, 62, 53, 68, 143, 180],
      "change": "Widen Warehouse enough for its longest full location while retaining naturally wrapped SKUs. This tests whether single-line locations improve row scanning enough to justify 80px of horizontal overflow."
    },
    {
      "name": "single-line",
      "widths": [38, 157, 61, 52, 47, 62, 53, 68, 143, 180],
      "change": "Give both SKU and Warehouse their full one-line widths. This should produce compact single-line rows and intact values, at the cost of 142px of horizontal overflow."
    },
    {
      "name": "viewport-fit",
      "widths": [38, 95, 61, 52, 47, 62, 53, 68, 102, 140],
      "change": "Fit the table within 719px by narrowing Tracking. This tests the no-scroll alternative, accepting mid-identifier splits and potentially taller rows."
    }
  ]
